/* Example: a simple grid container */
.grid-example {
  display: grid;
  grid-template-columns: repeat(2, 150px);
  grid-template-rows: repeat(2, 150px);
  gap: 20px;
}

/* Example: styling a box element */
.box {
  background-color: lightblue;
  border: 2px solid navy;
  padding: 20px;
  text-align: center;
}

